"""Editorial task answers. Recipe facts live in ball_x_pit_data, not this prose."""
P='/ball-x-pit/'
def link(slug,label):return f'<a href="{P}{slug}/">{label} →</a>'
def paras(*texts):return ''.join('<p>'+s+'</p>' for s in texts)
def items(*texts):return '<ol>'+''.join('<li>'+s+'</li>' for s in texts)+'</ol>'
def table(head,rows):return '<div class="table-wrap"><table><thead><tr>'+''.join('<th scope="col">'+x+'</th>' for x in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+x+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def spec(slug,title,desc,h1,answer,parts,related):
 return dict(slug=slug,title=title,desc=desc,h1=h1,answer=answer,parts=parts,related=related)
def pages():
 return [
 spec('evolutions','Ball x Pit Evolutions: Recipes & Prerequisite Finder','Find Ball x Pit evolution recipes, expand prerequisite chains and account for balls you already carry. Includes base-game and free-update combinations.',
 'Ball x Pit evolution recipes & prerequisite finder',
 'Evolution creates a specific new ball from a recipe; ordinary Fusion combines effects. Choose a target below to see its intermediate recipes and missing starting materials. Satan needs Incubus + Succubus; Nosferatu needs three evolved balls. [source:base]',
 [('finder','Find a recipe route','@ball-tool'),
 ('steps','Make the recipe, then choose Evolution',paras('Pick the required balls during the same run and upgrade the ingredients. At the fusion core, use the Evolution option for a listed recipe. A generic fused name is not the same discovery as the named evolution you were chasing. The community instructions explicitly describe maxing components and selecting the matching Evolution option. [source:shadow]',
 'The finder plans ingredients, not drops or level-up offers. An ingredient marked missing can still be locked on your save. A route is not a guarantee that your next reward will offer it. If the option is absent, compare the exact ingredient names, their levels, and the selected core action before spending more rerolls.')),
 ('recipes','Recipe chart: base game and free updates','@ball-table'),
 ('cell','What Cell contributes',paras('Cell is an input, not another spelling for Maggot. Brood Mother + Cell makes Maggot; Earthquake + Cell makes Overgrowth; Egg Sac + Cell makes Voluptuous Egg Sac. Choose the branch that supports your current run instead of treating every Cell pickup as a reason to chase the same endpoint. [source:base]')),
 ('maggot','Maggot: recipe versus a build',paras('Use Brood Mother + Cell to evolve Maggot. Its baby-ball role explains why it appears in community combinations with other effects, but obtaining it alone is not a complete build. The '+link('builds','build guide')+' separates early clearance from later swarm combinations. [source:base]')),
 ('satan','Satan: keep both branches available',items('Charm + Dark → Incubus.','Charm + Vampire → Succubus.','Incubus + Succubus → Satan.')+paras('Charm occurs on both branches. The route finder deliberately counts repeated starting ingredients; it does not claim all of them must occupy slots simultaneously. Build intermediate evolutions in sequence and check your available offers. If you already hold Incubus, select it as carried to remove that branch from the remaining-material list. [source:base]')),
 ('nosferatu','Nosferatu: three evolved ingredients',items('Vampire + Bleed → Vampire Lord; Vampire + Dark is another documented route.','Brood Mother + Egg Sac → Spider Queen.','Vampire + Brood Mother → Mosquito King.','Keep the three evolved outputs, then choose the Nosferatu evolution.')+paras('The three outputs are the final recipe, not any three vampire-themed balls. The default tree uses the first listed Vampire Lord route. Alternative routes are shown in the chart; do not mistake the default route for the only valid one. [source:base]')),
 ('method','Method, names and limits',paras('This is a source-based ingredient graph checked on 30 October 2026, covering the base game and documented Regal, Shadow and Naturalist recipes. It does not include unreleased Risen Ballbylon recipes. Each chart row links to a numbered source; there is no damage score or claimed DPS multiplier.',
 'The route tree follows one documented recipe per output, stops at balls you mark as carried, and totals repeated leaf ingredients. It does not optimize pickup order, validate slot capacity, simulate random offers or check your save. Alternate recipes remain visible in the table. “Fire/Ice/Darkness/Egg Sack” in older community posts are normalized here to Burn/Freeze/Dark/Egg Sac. Offspring and Petrify are the English guide names for outputs called Embryo and Medusa in one Naturalist comment. [source:recipes]'))],
 ['passive-evolutions','new-evolutions','builds']),
 spec('passive-evolutions','Ball x Pit Passive Evolutions: Recipes & Slot Checks','Plan Ball x Pit passive evolutions with ingredient chains, capacity checks and a clear core-selection process. Includes recipes from the free updates.',
 'Ball x Pit passive evolutions & ingredient checks',
 'Collect compatible passives, upgrade them fully, then pick up a fusion core and choose Evolution. Passives use their own recipe list: a ball recipe cannot evolve an item. Start with your target and check the required item slots before committing. [source:shadow]',
 [('finder','Plan a passive recipe','@passive-tool'),
 ('process','Three checks before spending rerolls',items('Check the exact item names. A similar effect or a similarly named ball is not a substitute.','Upgrade the matching ingredients fully in this run. Owning their encyclopedia entries is not carrying them.','At the core select Evolution and the named result, rather than assuming possession automatically transforms items.')+paras('hashtagtylerh explains this process with Arrow of Fate: Lover’s Quiver + Hand Mirror. That is a community procedure, not a test performed by this website. [source:shadow]')),
 ('recipes','Passive recipe table','@passive-table'),
 ('slots','Capacity and irreversible choices',paras('Deadeye’s Cross takes four distinct dagger ingredients. Check whether your character and current progression can hold all four before making it the run’s goal. The plan lists dependencies, not the number of simultaneous slots needed by every intermediate stage. [source:base]',
 'The Ballbearer gives up passive items; it is therefore the wrong choice for a passive-recipe run. The Hoary Hoarder has extra passive capacity but only two ball slots. That trade is useful for item hunting and limiting for deep ball chains. Select for the task, rather than following one overall character tier. [source:news]',
 'DCRage’s guide describes chosen passives as not freely replaceable. Keep room for your target ingredients instead of filling every slot with unrelated bonuses first. The guide contains conflicting update chronology and some disputed effect values, which are excluded from this planner. [source:passives]')),
 ('soul-reaver','Soul Reaver is a passive, not Soul Sucker',paras('Soul Reaver uses Vampiric Sword + Everflowing Goblet. Soul Sucker is a ball with a different recipe. If searching for Soul Reaver produced a vampire/ghost ball chart, switch to the passive recipe here. This distinction matters when reserving item slots. [source:passives]')),
 ('hidden','Missing items may have appearance conditions',paras('A missing Ghostly Shield is not evidence that you need another passive evolution. The '+link('ghostly-shield','Ghostly Shield guide')+' explains its stone-ally requirement, random offer and encyclopedia registration. A recipe helper cannot determine whether you have met that requirement in your live run. [source:shield]'))],
 ['evolutions','ghostly-shield','characters']),
 spec('builds','Ball x Pit Builds: Choose Combos by Progression','Choose Ball x Pit builds for your unlocked roster and goal. Compare short evolution routes, dual-character pairings and reported late-run synergies.',
 'Ball x Pit builds: choose for the run you can play',
 'For early clears, prefer a short evolution you can finish with your current offers. After unlocking two-character runs, choose a pairing whose firing rules support the same plan. Community favourites differ between clearance, long runs and manual play; these are reported options, not our tested universal ranking. [source:base][source:pairs]',
 [('choose','Choose a starting plan',table(['Your situation','Start with','Avoid committing to'],[
 ['Only early ingredients available','Bomb (Burn + Iron) or Magma (Burn + Earthquake) if offered','A multi-stage Satan/Nosferatu route with ingredients still locked'],
 ['You want baby-ball synergies','Maggot via Cell + Brood Mother, then evaluate an effect to combine with it','The Empty Nester, whose rule removes baby balls'],
 ['You have AoE ingredients and dual characters','Consider the reported Sisyphus + Empty Nester pairing','Mixing a baby-ball plan into a no-baby-ball pairing'],
 ['You are collecting recipes','Choose capacity for your target: balls or passives','Treating a collection run like a fastest-clear challenge']])+paras('These are route and compatibility decisions. The early recipes and Maggot ingredient list are documented in the release community chart; the pairing suggestions come from player reports. [source:base][source:pairs]')),
 ('early','Build a short route before a long chain',items('Look at the balls already offered, then pick one reachable output. Use the recipe finder to check the remaining ingredients.','Make that first evolution before committing to a second long branch. Nuclear Bomb can extend a Bomb route with Poison; Satan starts from two separate evolutions.','If offers do not support the plan, keep a functional short route rather than spending the entire run searching for a theoretical best build.')+paras('The last step is our planning recommendation based on recipe length, not a measured reroll threshold. We do not publish invented gold cutoffs, damage multipliers or a guaranteed win rate. [source:base]')),
 ('pairs','Dual-character pairings by constraint',table(['Pair reported by players','Why consider it','Check before choosing'],[
 ['Sisyphus + Empty Nester','Commit to a special-ball/AoE plan','Do not also depend on baby-ball generation'],
 ['Juggler + Falconer','Player-described aiming and launch interaction','Both must actually be unlocked; this is not a first-run option'],
 ['Cohabitants + Tunneler','Player preference for keeping attacks active','Manual feel and available balls still matter'],
 ['Embedded + Ballbearer','Player-described penetration with a large ball loadout','Ballbearer gives up passive items; do not plan item-based sustain']])+paras('W0mb0C0mb019’s question specifically says they had only reached Juggler. A good answer must respect that roster rather than recommend only late unlocks. Respondents disagree strongly on Spendthrift + Falconer and other “best” combinations, so no single comment is treated as benchmark proof. Exact post dates were not reliably exposed by the reader. [source:pairs]')),
 ('baby-balls','Baby-ball and longer-run reports',paras('The older release discussion suggests combining baby-ball generators with effects that benefit from many hits. Later Shadow comments discuss Reaper with Maggot and other combinations. These reports establish ideas to try, not guaranteed boss interactions after every patch. Keep a separate answer for “how do I get the ingredients?” and “does this help my current run?” [source:base][source:shadow]',
 'If you want Maggot, the route is Cell + Brood Mother. For Reaper, first make Soul Sucker and Heart Swallower. That is a longer commitment; inspect the full tree before sacrificing a working early setup. [source:shadow]')),
 ('limits','What this guide does not rank',paras('No DPS tests, controller tests or complete runs were performed by Megabonk.org. Rankings based on undisclosed difficulty and unlocks are not directly comparable. Use the '+link('character-tier-list','conditional character recommendations')+' for the roster decision and the '+link('characters','unlock checks')+' when a recommended partner is unavailable. Risen Ballbylon builds are excluded until the expansion is released and sourced.'))],
 ['character-tier-list','evolutions','beginners-guide']),
 spec('character-tier-list','Ball x Pit Character Tier List: Conditional Picks','Choose Ball x Pit characters by progression, controls and partner compatibility. Compare published rankings, player disagreements and slot trade-offs.',
 'Ball x Pit character tier list: picks with conditions',
 'Choose a character for the run’s task: a conventional pick for learning, a compatible pair for your build, or extra capacity for collecting recipes. Published tiers and community preferences disagree. The table below makes those conditions explicit instead of presenting an untested best-to-worst score. [source:tier][source:pairs]',
 [('picks','Which character should you choose?',table(['Use case','Recommended shortlist','Reason and limit'],[
 ['Learning the run loop','Warrior, then try an unlocked conventional shooter','Warrior is the starting character; prioritize learning pickups and the town loop'],
 ['An aggressive conventional recommendation','Itchy Finger / Embedded / Repentant','Dexerto places these highly; that is an attributed editorial ranking, not a promise at every difficulty'],
 ['A manual bounce-focused pairing','Consider Flagellant or Tunneler once available','Community respondents value keeping balls active; published lists disagree about Flagellant'],
 ['Collecting ball evolutions','Ballbearer','More ball slots, no passive items: ball-heavy plans must solve sustain without an item loadout'],
 ['Collecting passive evolutions','Hoary Hoarder','More passive room but two ball slots; do not choose it for a deep multi-ball chain'],
 ['A special-ball plan without baby balls','Empty Nester with a compatible partner','The firing rule changes the build; do not combine it with a baby-ball-dependent goal']])+paras('Character mechanics and slot trade-offs are supported by the developer’s Naturalist announcement. Ranked preferences come from Dexerto and the pairing thread. [source:news][source:tier][source:pairs]')),
 ('disagreement','Why the published tiers disagree',paras('Dexerto places Flagellant lower than several standard shooters, while respondents in the pairing thread recommend it enthusiastically. That does not establish a patch change or a measured error: the sources do not share a controlled difficulty, build or input setup. Treat it as a reason to ask what the rank is optimizing. [source:tier][source:pairs]',
 'Before following a tier, write down your goal: first clear, a longer run, an encyclopedia entry, or a trophy clear with a particular character. A collector’s extra slots and a manual player’s preferred bounce pattern are different advantages. Our shortlist organizes those decisions without fabricating a combined score.')),
 ('partners','When you can bring two characters',paras('First confirm that you can select the partner and have built the Matchmaker. Match the pair’s rules to the balls and items you want to use. A no-baby-ball partner invalidates a baby-ball plan; a character with no passives invalidates a passive-recipe plan. The '+link('builds','pairing table')+' gives reported combinations and their constraints. [source:trophy][source:news][source:pairs]')),
 ('unlock','If a recommended character is missing',paras('Use the '+link('characters','character and blueprint checks')+' to identify the corresponding house, inspect the stage’s blueprint indicator and finish construction back at town. This page recommends among options you can use; it does not guarantee a particular blueprint will drop in the next run. [source:characters][source:shadow]'))],
 ['builds','characters','passive-evolutions']),
 spec('beginners-guide','Ball x Pit Beginner Guide: First Runs & Upgrades','Start Ball x Pit with a clear run-to-town loop: choose a short recipe, collect resources, finish construction and understand Fusion versus Evolution.',
 'Ball x Pit beginner guide: your first runs & upgrades',
 'Play one short, reachable ball recipe during the run, then return to town and turn blueprints and resources into upgrades. Evolution and Fusion are different choices. Do not make a rare endgame recipe the requirement for learning the first stages. [source:official][source:trophy][source:base]',
 [('start','Your first run-to-town loop',items('Start with Warrior, the available starting character. Watch the movement and firing prompts for your input device; this guide does not prescribe unverified controller button mappings.','Collect experience and choose upgrades that move toward one reachable recipe. Burn + Iron makes Bomb; Burn + Earthquake makes Magma.','Compare the exact components before selecting Evolution at a core. A generic Fusion is not the named evolution entry.','Collect blueprints and resources, then inspect the town after the run. A lost run can still teach you which upgrades and buildings you need.')+paras('Recipes are community-documented; town construction is described in Dayngls’ base-game guide. Recommendations about keeping the first route short are editorial planning advice, not a claimed optimal speedrun. [source:base][source:shadow][source:trophy]')),
 ('town','Finish a building, not just its placement',items('Check that you have acquired its blueprint and can pay its material requirements.','Place the structure where your harvest launch can reach it.','Use Harvest and bounce characters into the construction to fill its meter.','Return to the appropriate menu to confirm the character or upgrade is actually available.')+paras('Dayngls explains that arranging reachable structures matters and that buildings can be repositioned. A blueprint, a placed construction site and a completed building are different stages of progress. If a new character is absent, check completion before assuming the drop was lost. [source:trophy]')),
 ('controls','Controls and clear feedback',paras('Follow the input prompts shown by your version. Aim to use wall rebounds while keeping room to avoid enemies. When a new menu option appears, read whether it is offering a level upgrade, an Evolution or a generic Fusion before confirming.',
 'The Steam game and mobile listing describe the same core loop but do not establish identical button mappings, save compatibility or performance. Use the '+link('','platform links').replace('/ball-x-pit//','/ball-x-pit/#platforms')+' for the correct store, rather than downloading a similarly named game. [source:official][source:ios]')),
 ('choices','Three common early detours',table(['Detour','Better next action'],[
 ['Trying to make Nosferatu before its branches are reachable','Use the recipe finder and focus on one short branch first'],
 ['Filling passive slots before choosing a target recipe','Reserve capacity for the target ingredients; do not confuse encyclopedia ownership with a carried item'],
 ['Repeating runs without finishing construction','Inspect blueprints, materials and the construction meter between runs']])+paras('This is a practical decision checklist assembled from the recipe and construction rules. It is not a list of measured failure rates. [source:base][source:trophy]')),
 ('next','Choose your next task',paras('For a missing ingredient, open '+link('evolutions','ball recipes')+'. For selecting a character, use '+link('character-tier-list','conditional picks')+'. For an item that never appears despite other progress, check '+link('ghostly-shield','Ghostly Shield’s appearance requirement')+'. Leave NG+ and Endless scaling claims aside until your question is specifically about those modes.'))],
 ['evolutions','characters','builds']),
 spec('ghostly-shield','Ball x Pit Ghostly Shield: Unlock & Missing Item Checks','Get Ghostly Shield into Ball x Pit’s item pool by meeting the stone-ally condition. Separate eligibility, random offers and encyclopedia registration.',
 'Ghostly Shield: why it is missing & what to check',
 'First take a passive that supplies a stone ally, such as an Effigy. Ghostly Shield can then appear as a random passive offer. Pick it during the run to register it in the encyclopedia; meeting the prerequisite alone does not fill the entry. [source:shield]',
 [('steps','A three-stage check',items('In a run, select a stone-ally/Effigy passive rather than only unlocking it on your save.','After that prerequisite, inspect subsequent passive choices. The report describes a chance to appear, not a guaranteed next-level offer.','Select Ghostly Shield when offered, then check its encyclopedia entry.')+paras('On 19 October 2025, Seasoul asked why Ghost Shield and Traitor’s Hood remained unknown despite extensive unlock progress. NyX gave the stone-ally prerequisite and Seasoul replied that it worked. This is one historical success report, not a measured probability or current-patch test by us. [source:shield]')),
 ('symptoms','Match the symptom to the next action',table(['What you see','What it means','Next check'],[
 ['The entry is still “???” before taking an Effigy','General progress has not proved the run-specific requirement','Take a stone-ally passive during the run'],
 ['You have an Effigy but have not seen the shield','Eligibility does not guarantee an immediate random offer','Check later offers and your available passive capacity'],
 ['You saw an offer but did not take it','Seeing the name is not the reported registration condition','Select it in a run when offered'],
 ['A guide tells you to fuse two passives for it','Appearance-gated passives and evolved passives are different tasks','Use the stone-ally check here; use the passive recipe guide for named evolutions']])),
 ('related-item','Traitor’s Cowl and friendly units',paras('The same Steam thread covers Traitor’s Cowl. The useful shared principle is the prerequisite: stone allies must be present before the relevant item can enter your run’s candidate pool. The thread does not establish a universal formula for every hidden item, and we do not infer one. [source:shield]',
 'Keep the exact English item name and game version when checking another guide. “Ghost Shield” and “Traitor’s Hood” are the wording in the original question; this page uses Ghostly Shield and Traitor’s Cowl to match the current English reference names.')),
 ('still-missing','If it still does not appear',paras('Record your game version, character, carried passives and whether you actually received a stone ally. Keep the level-up screen or an item description if you request help. One unsuccessful run does not disprove a chance-based prerequisite; equally, an old success reply does not prove a guaranteed current drop.',
 'If your character cannot take passives, switch before trying an item-collection run. The developer specifically describes Ballbearer as giving up passive items. No fixed reroll cost, required number of runs or drop percentage is verified here. [source:news]'))],
 ['passive-evolutions','characters','trophy-guide']),
 spec('new-evolutions','Ball x Pit New Evolutions: Free-Update Recipe Index','Find Ball x Pit recipes added by Regal, Shadow and Naturalist, with update filters and links to ingredient routes. Risen Ballbylon is marked separately.',
 'New Ball x Pit evolutions: find what your old chart misses',
 'Use the update filter to find Regal, Shadow or Naturalist recipes without re-reading the base chart. Stone, Time and Flesh belong to different update sets. Risen Ballbylon is announced for 12 November 2026 and is excluded from these released-game recipes. [source:news]',
 [('lookup','Look up an added recipe','@new-tool'),
 ('regal','Regal: start with Stone',paras('The developer dates Regal to 26 January 2026. The community recipe post distinguishes Stone from Steel: Iron + Stone makes Steel, and Steel + a base Horizontal or Vertical Laser makes Laser Cutter. Laser Beam is a different ingredient and is not the substitute in that recipe. [source:news][source:regal]')),
 ('shadow','Shadow: Time and longer chains',paras('The 27 April update introduced the Shadow set. Its community chart includes Time-based routes, Reaper and X Ray. For Reaper, plan Soul Sucker + Heart Swallower; for X Ray, plan Holy Laser + Laser Beam. Search a target above to expand the branches rather than collecting only the final names. [source:news][source:shadow]')),
 ('naturalist','Naturalist: Flesh and four-input Elemental',paras('The 6 August update is the final announced free content update. The developer describes the Ballbearer and Hoary Hoarder’s opposing capacities. They are useful for different collection jobs; the item specialist is not automatically the easiest choice for a deep ball chain. [source:news]',
 '<span id="elemental"></span>Elemental uses Burn + Freeze + Earthquake + Wind in the Naturalist community list. Its four-input recipe is a reason to check capacity. One source calls Flesh + Cell “Embryo” and Flesh + Stone “Medusa”; the English guide names those outputs Offspring and Petrify. The finder uses the English names; these alternate labels are explained here. [source:naturalist][source:recipes]')),
 ('added-passives','Added passive recipes','@new-passive-table'),
 ('risen','Risen Ballbylon: keep announced content separate',paras('The developer’s 20 September announcement gives 12 November as the planned release and says the expansion is entered after completing the base game. This guide does not invent recipes for its advertised balls, characters or passives. A search for “new evolutions” can currently mean an older free update or this forthcoming expansion; check the name before following steps. [source:news]')),
 ('chart','All added ball recipes','@new-ball-table')],
 ['evolutions','passive-evolutions','characters']),
 spec('characters','Ball x Pit Characters: Houses & Blueprint Unlock Checks','Find the house associated with each Ball x Pit character and check blueprint discovery, materials and construction before expecting a roster unlock.',
 'Ball x Pit characters: houses & unlock checks',
 'Unlock a character by finding the relevant house blueprint and completing construction in town. Warrior is available from the start. The table maps characters to houses; it does not promise a fixed next-run blueprint drop or an exact biome reward. [source:characters][source:trophy]',
 [('checks','Find out which unlock step is missing',items('Identify the house in the table below. Check whether its blueprint has actually been acquired.','Use the stage-selection blueprint indicator to see whether there is still a blueprint available there, as described in the Shadow community thread.','Back in town, check the required materials and place the building.','Use Harvest to complete construction, then inspect character selection again.')+paras('The stage indicator is a community-reported check, not a claim that all houses have the same fixed location. Some guides give fixed biome mappings while others describe random blueprint drops. We preserve the reliable house association and construction process without promising a specific run’s reward. [source:shadow][source:trophy]')),
 ('houses','Characters and their houses','@character-table'),
 ('new-hunters','Which free-update characters am I looking for?',table(['Update','Characters','Task constraint'],[
 ['Regal','Falconer / Carouser','Check Falconry Hut / Party House construction'],
 ['Shadow','Tunneler / Tiptoer','Check Stone Domain / Hidden Temple'],
 ['Naturalist','Ballbearer / Hoary Hoarder','Check Ball House / Unstable Tower; choose ball or item capacity']])+paras('The developer announcements confirm the free-update sets and the character rules. The house associations come from the English character guide. Names and unlocks do not include the unreleased Risen roster. [source:news][source:characters]')),
 ('construction','The blueprint is not the finished house',paras('If the blueprint is present but the character is absent, look for an incomplete construction meter. Dayngls describes bouncing the harvest characters into a structure to finish it. Place it where those launches can reach it; check the meter rather than assuming paying the material cost instantly unlocks the character. [source:trophy]')),
 ('choose','Once the character appears',paras('Pick for your immediate task. Ballbearer’s additional ball slots cost all passive items; Hoary Hoarder trades ball capacity for passive room. Use '+link('character-tier-list','conditional character picks')+' for the decision and '+link('trophy-guide','the trophy route')+' to avoid repeating already-finished character/stage combinations. [source:news]'))],
 ['character-tier-list','trophy-guide','new-evolutions']),
 spec('trophy-guide','Ball x Pit Trophy Guide: Route & Clear Checklist','Plan Ball x Pit’s base-game trophies with a character-by-stage clear checklist, Matchmaker pairing checks and links to missing evolution requirements.',
 'Ball x Pit trophy guide: route & clear checklist',
 'Build your permanent upgrades and the Matchmaker, then track stage clears by character. The base-game trophy guide reports that a two-character clear counts for both. Save named evolution and missing-encyclopedia checks for targeted runs rather than treating every clear as a collection run. [source:trophy]',
 [('route','A route that reduces repeat clears',items('Progress through the stages while collecting resources and blueprints. Finish useful construction between runs.','When available, complete the Matchmaker so you can select two characters.','Use the matrix below to record your actual clears. Pair characters still missing the same stage instead of repeating a completed pair.','Review the in-game trophy description and encyclopedia for the remaining tasks. Use a deliberate ingredient route for Satan or Nosferatu, and a separate appearance-condition check for hidden passives.')+paras('This sequence combines the published base-game route with a planning checklist. The matrix is your record, not a connection to the game or a trophy-unlock service. [source:trophy]')),
 ('checklist','Character × stage clear checklist','@trophy-tool'),
 ('collect','Separate the collection tasks',table(['What is missing','Use this task','What not to assume'],[
 ['Satan or Nosferatu','Expand the named evolution’s prerequisite route','Any similarly named fused ball counts as the named evolution'],
 ['Ghostly Shield / Traitor’s Cowl','Meet the stone-ally condition, then take the offered passive','Unlocking all characters automatically registers all items'],
 ['A passive evolution','Reserve ingredient slots, upgrade and choose Evolution','Owning encyclopedia entries means carrying the components'],
 ['A stage-clear trophy','Read its current required characters/count and check the clear record','Later DLC characters necessarily share the original trophy rules']])+paras('The named recipes, hidden-item report and item-evolution instructions are separate evidence chains. [source:base][source:shield][source:shadow]')),
 ('time','How long does completion take?',paras('Dayngls estimates 25–30 hours for its base-game trophy route. That is an author estimate for that route, not a promise for a first clear, every platform or the forthcoming expansion. Your unlocks, building progress and repeated clears can change the workload. [source:trophy]')),
 ('scope','Base-game scope and checklist storage',paras('This checklist uses the original 16-character roster and eight stage names. It deliberately excludes free-update/DLC characters from the trophy matrix because the original trophy requirements must be checked in your version. A checked cell is a manual note, not verified completion.',
 'Ticks are saved only in this browser’s local storage. They do not sync to Steam, a console or your game save. Use Reset to remove this checklist from the device; private browsing or cleared site data may erase it. The page works as a printable table when JavaScript is unavailable.'))],
 ['characters','evolutions','ghostly-shield'])
 ]
